function renderAnalyticsChart(d,i){const s=document.getElementById(d);if(!s)return;const o=localStorage.getItem(i);if(!o)return;const n=JSON.parse(o),l=Object.keys(n).sort((t,e)=>{const a=r=>{const c=r.match(/q(\d+)/i);return c?parseInt(c[1]):0};return a(t)-a(e)}),u=l.map(t=>n[t]),b=l.map(t=>{const e=t.match(/q(\d+)/i);return e?`Q${e[1]}`:t});new Chart(s,{type:"bar",data:{labels:b,datasets:[{label:"Time Spent",data:u,backgroundColor:"rgba(123, 31, 162, 0.6)",borderColor:"rgba(123, 31, 162, 1)",borderWidth:1,borderRadius:4,hoverBackgroundColor:"rgba(123, 31, 162, 0.8)"}]},options:{responsive:!0,maintainAspectRatio:!1,scales:{y:{beginAtZero:!0,title:{display:!0,text:"Seconds"},grid:{color:"rgba(0, 0, 0, 0.05)"}},x:{grid:{display:!1}}},plugins:{legend:{display:!1},tooltip:{callbacks:{label:t=>{const e=t.parsed.y,a=Math.floor(e/60),r=e%60;return`Time: ${a}m ${r}s`}}}}}})}
